questionvariables.text:
price: 10*rand_with_prohib(5,20,[]);
/* Option values are neutral literals so the page source does not reveal the answer;
   the correct option is not listed first. */
opts: [
  ["opt1", false, "\\(n\\) can be any real number, since \\(R(n)\\) can be evaluated for every real \\(n\\)."],
  ["opt2", false, "\\(n\\) can be any positive real number, including fractions such as \\(2.5\\)."],
  ["opt3", true, "\\(n\\) must be a non-negative whole number (\\(0, 1, 2, 3, \\ldots\\)), since you cannot sell a negative or fractional number of tickets."],
  ["opt4", false, "\\(n\\) can be any integer, including negative integers."]
];
